	@ParameterizedTest(name = "{0} returns {1} rows")
	@MethodSource("generatedQueries")
	void generatedQueryRunsOnRdf4jAndReturnsTheExpectedRows(String name, int expectedRows) throws IOException {
		String query = fixture(name + ".rq");
		int rows = 0;
		try (RepositoryConnection connection = repository.getConnection();
				TupleQueryResult result = connection.prepareTupleQuery(QueryLanguage.SPARQL, query).evaluate()) {
			while (result.hasNext()) {
				BindingSet row = result.next();
				rows++;
				if (name.startsWith("neighbors")) {
					assertThat(row.getValue("selected")).as("per-node result key of %s", name).isNotNull();
				}
			}
		}
		assertThat(rows).as(name).isEqualTo(expectedRows);
	}

	@ParameterizedTest(name = "{0} restricts every scoped pattern to its node")
	@ValueSource(strings = { "facet-statements", "facet-statements-all", "facet-statements-named", "facet-census",
			"facet-values", "facet-exact-values", "facet-exact-values-all", "facet-value-labels" })
	void repositoryFacetQueriesNeverHashJoinAnUnrestrictedScan(String name) throws IOException {
		// A GRAPH pattern or a subquery is evaluated on its own: a VALUES block outside it would not restrict it, and
		// the
		// join would read every statement of the scope. The Filters panel's queries keep VALUES inside the pattern.
		try (RepositoryConnection connection = repository.getConnection()) {
			TupleQuery query = connection.prepareTupleQuery(QueryLanguage.SPARQL, fixture(name + ".rq"));
			String plan = query.explain(Explanation.Level.Executed).toString();
			assertThat(plan).as(plan)
					.doesNotContain("HashJoinIteration")
					.doesNotContain("name=s) (bindingState=unbound)");
		}
	}

